def rle_encode(s: str) -> str:
    if not s:
        return ""
    parts = []
    prev = s[0]
    count = 0
    for ch in s:
        if ch == prev:
            count += 1
        else:
            parts.append(str(count) + prev)
            prev = ch
            count = 1
    parts.append(str(count) + prev)
    return "".join(parts)


def rle_decode(s: str) -> str:
    if not s:
        return ""
    result = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("missing run length")
        length = int(s[i:j])
        if length <= 0:
            raise ValueError("run length must be positive")
        if j >= n:
            raise ValueError("dangling run length")
        ch = s[j]
        if not (("a" <= ch <= "z") or ("A" <= ch <= "Z")):
            raise ValueError("invalid character")
        result.append(ch * length)
        i = j + 1
    return "".join(result)
